# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GERÇEK SAYI DİZİSİ: f : Z⁺ → R, f(n) = aₙ</text>\n  <!-- Tanım Kümesi Z+ -->\n  <ellipse cx="145" cy="140" rx="85" ry="90" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="145" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tanım Kümesi (Z⁺)</text>\n  <text x="145" y="86" text-anchor="middle" font-size="11" fill="#3b82f6">(Pozitif Tam Sayılar / İndis)</text>\n  <circle cx="145" cy="112" r="14" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="145" y="117" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">1</text>\n  <circle cx="145" cy="147" r="14" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="145" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">2</text>\n  <circle cx="145" cy="182" r="14" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="145" y="187" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">3</text>\n  <circle cx="145" cy="214" r="14" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="145" y="219" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">n</text>\n\n  <!-- Görüntü Kümesi R -->\n  <ellipse cx="385" cy="140" rx="95" ry="90" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="385" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Görüntü Kümesi (⊂ R)</text>\n  <text x="385" y="86" text-anchor="middle" font-size="11" fill="#16a34a">(Dizinin Terimleri)</text>\n  <rect x="335" y="99" width="100" height="24" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="385" y="116" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">f(1) = a₁</text>\n  <rect x="335" y="134" width="100" height="24" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="385" y="151" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">f(2) = a₂</text>\n  <rect x="335" y="169" width="100" height="24" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="385" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">f(3) = a₃</text>\n  <rect x="335" y="201" width="100" height="24" rx="6" fill="#bbf7d0" stroke="#15803d"/>\n  <text x="385" y="218" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">f(n) = aₙ</text>\n\n  <!-- Oklar -->\n  <line x1="162" y1="112" x2="330" y2="112" stroke="#475569" stroke-width="1.8" stroke-dasharray="4,3"/>\n  <polygon points="333,112 325,108 325,116" fill="#475569"/>\n  <line x1="162" y1="147" x2="330" y2="147" stroke="#475569" stroke-width="1.8" stroke-dasharray="4,3"/>\n  <polygon points="333,147 325,143 325,151" fill="#475569"/>\n  <line x1="162" y1="182" x2="330" y2="182" stroke="#475569" stroke-width="1.8" stroke-dasharray="4,3"/>\n  <polygon points="333,182 325,178 325,186" fill="#475569"/>\n  <line x1="162" y1="214" x2="330" y2="214" stroke="#1e293b" stroke-width="2"/>\n  <polygon points="333,214 325,210 325,218" fill="#1e293b"/>\n  <text x="248" y="207" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Genel Terim</text>\n\n  <!-- Sağ Bilgi Kutusu -->\n  <rect x="500" y="55" width="182" height="175" rx="8" fill="#fff1f2" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="591" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">DİZİ OLMA ŞARTI</text>\n  <line x1="512" y1="84" x2="670" y2="84" stroke="#fda4af" stroke-width="1"/>\n  <text x="512" y="104" font-size="10.5" fill="#881337">• (n+1)/(n-3) ifadesi:</text>\n  <text x="518" y="120" font-size="10" fill="#9f1239">n = 3 ∈ Z⁺ için tanımsız</text>\n  <text x="518" y="134" font-size="10" font-weight="bold" fill="#be123c">→ Dizi belirtmez!</text>\n  <text x="512" y="158" font-size="10.5" fill="#881337">• Kök içinde (n-4) ifadesi:</text>\n  <text x="518" y="174" font-size="10" fill="#9f1239">n ∈ {1,2,3} için ∉ R</text>\n  <text x="518" y="188" font-size="10" font-weight="bold" fill="#be123c">→ Gerçek dizi belirtmez!</text>\n  <text x="591" y="216" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">Her n ∈ Z⁺ için aₙ ∈ R olmalı!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SONLU DİZİ, SABİT DİZİ VE EŞİT DİZİLER</text>\n\n  <!-- Kart 1: Sonlu Dizi -->\n  <rect x="18" y="48" width="212" height="192" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="124" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. SONLU DİZİ</text>\n  <line x1="32" y1="82" x2="216" y2="82" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="124" y="104" text-anchor="middle" font-size="11" fill="#1e3a8a">k ∈ Z⁺ olmak üzere;</text>\n  <rect x="34" y="114" width="180" height="28" rx="6" fill="#dbeafe"/>\n  <text x="124" y="133" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Aₖ = {1, 2, 3, ..., k}</text>\n  <text x="124" y="160" text-anchor="middle" font-size="10.5" fill="#1e3a8a">kümesinden R\'ye tanımlı</text>\n  <text x="124" y="176" text-anchor="middle" font-size="10.5" fill="#1e3a8a">f : Aₖ → R fonksiyonuna</text>\n  <text x="124" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">k terimli sonlu dizi denir.</text>\n  <text x="124" y="222" text-anchor="middle" font-size="10.5" fill="#0f172a">(a₁, a₂, a₃, ..., aₖ)</text>\n\n  <!-- Kart 2: Sabit Dizi -->\n  <rect x="244" y="48" width="212" height="192" rx="10" fill="#fefce8" stroke="#eab308" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. SABİT DİZİ</text>\n  <line x1="258" y1="82" x2="442" y2="82" stroke="#fde047" stroke-width="1.5"/>\n  <text x="350" y="104" text-anchor="middle" font-size="11" fill="#713f12">Her n ∈ Z⁺ için c ∈ R:</text>\n  <rect x="264" y="114" width="172" height="28" rx="6" fill="#fef08a"/>\n  <text x="350" y="133" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">aₙ = c = (c, c, c, ...)</text>\n  <text x="350" y="160" text-anchor="middle" font-size="10.5" fill="#713f12">aₙ = (p·n + r) / (s·n + t)</text>\n  <text x="350" y="178" text-anchor="middle" font-size="10.5" fill="#713f12">ifadesi sabit dizi ise:</text>\n  <rect x="284" y="190" width="132" height="34" rx="6" fill="#fde047" stroke="#ca8a04"/>\n  <text x="350" y="212" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">p / s = r / t = c</text>\n\n  <!-- Kart 3: Eşit Diziler -->\n  <rect x="470" y="48" width="212" height="192" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="2"/>\n  <text x="576" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. EŞİT DİZİLER</text>\n  <line x1="484" y1="82" x2="668" y2="82" stroke="#86efac" stroke-width="1.5"/>\n  <text x="576" y="104" text-anchor="middle" font-size="11" fill="#14532d">Her n ∈ Z⁺ için:</text>\n  <rect x="490" y="114" width="172" height="28" rx="6" fill="#dcfce7"/>\n  <text x="576" y="133" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">aₙ = bₙ  ⇔  (aₙ) = (bₙ)</text>\n  <text x="576" y="162" text-anchor="middle" font-size="10.5" fill="#14532d">Örnek:</text>\n  <text x="576" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">aₙ = (-1)ⁿ</text>\n  <text x="576" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">bₙ = cos(n·π)</text>\n  <text x="576" y="220" text-anchor="middle" font-size="10.5" fill="#0f172a">(-1, 1, -1, 1, ...) → aₙ = bₙ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">FİBONACCİ, ÜÇGENSEL VE KARESEL SAYI DİZİLERİ</text>\n\n  <!-- Sol Kutu: Fibonacci -->\n  <rect x="16" y="42" width="215" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="123" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">FİBONACCİ DİZİSİ</text>\n  <text x="123" y="84" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">F₁ = 1, F₂ = 1</text>\n  <rect x="30" y="94" width="186" height="26" rx="6" fill="#f3e8ff"/>\n  <text x="123" y="112" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Fₙ = Fₙ₋₁ + Fₙ₋₂ (n ≥ 3)</text>\n  <text x="123" y="138" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#3b0764">1, 1, 2, 3, 5, 8, 13, 21, 34...</text>\n  <text x="123" y="162" text-anchor="middle" font-size="10" fill="#6b21a8">• İndirgemeli dizi örneğidir.</text>\n  <text x="123" y="180" text-anchor="middle" font-size="10" fill="#6b21a8">• Ayçiçeği, çam kozalağı,</text>\n  <text x="123" y="196" text-anchor="middle" font-size="10" fill="#6b21a8">  salyangoz kabuğunda görülür.</text>\n  <text x="123" y="222" text-anchor="middle" font-size="10" font-weight="bold" fill="#581c87">Her terim önceki 2 terimin toplamı</text>\n\n  <!-- Orta Kutu: Üçgensel Sayılar -->\n  <rect x="243" y="42" width="215" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#c2410c">ÜÇGENSEL SAYILAR</text>\n  <rect x="258" y="74" width="184" height="26" rx="6" fill="#ffedd5"/>\n  <text x="350" y="92" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">aₙ = n·(n + 1) / 2</text>\n  <!-- Nokta modelleri -->\n  <circle cx="280" cy="135" r="4.5" fill="#ea580c"/>\n  <text x="280" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#7c2d12">a₁=1</text>\n\n  <circle cx="335" cy="122" r="4.5" fill="#ea580c"/>\n  <circle cx="327" cy="135" r="4.5" fill="#ea580c"/>\n  <circle cx="343" cy="135" r="4.5" fill="#ea580c"/>\n  <text x="335" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#7c2d12">a₂=3</text>\n\n  <circle cx="405" cy="112" r="4" fill="#ea580c"/>\n  <circle cx="397" cy="124" r="4" fill="#ea580c"/>\n  <circle cx="413" cy="124" r="4" fill="#ea580c"/>\n  <circle cx="389" cy="136" r="4" fill="#ea580c"/>\n  <circle cx="405" cy="136" r="4" fill="#ea580c"/>\n  <circle cx="421" cy="136" r="4" fill="#ea580c"/>\n  <text x="405" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#7c2d12">a₃=6</text>\n\n  <text x="350" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">(1, 3, 6, 10, 15, 21, ...)</text>\n  <text x="350" y="206" text-anchor="middle" font-size="10" fill="#7c2d12">1\'den n\'ye ardışık doğal</text>\n  <text x="350" y="222" text-anchor="middle" font-size="10" fill="#7c2d12">sayıların toplamıdır.</text>\n\n  <!-- Sağ Kutu: Karesel Sayılar -->\n  <rect x="470" y="42" width="214" height="202" rx="10" fill="#ecfdf5" stroke="#0d9488" stroke-width="2"/>\n  <text x="577" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0f766e">KARESEL SAYILAR</text>\n  <rect x="485" y="74" width="184" height="26" rx="6" fill="#ccfbf1"/>\n  <text x="577" y="92" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#115e59">bₙ = 1+3+...+(2n-1) = n²</text>\n  <!-- Kare nokta modelleri -->\n  <circle cx="508" cy="134" r="4.5" fill="#0d9488"/>\n  <text x="508" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#134e4a">b₁=1</text>\n\n  <circle cx="555" cy="121" r="4.5" fill="#0d9488"/>\n  <circle cx="569" cy="121" r="4.5" fill="#0d9488"/>\n  <circle cx="555" cy="135" r="4.5" fill="#0d9488"/>\n  <circle cx="569" cy="135" r="4.5" fill="#0d9488"/>\n  <text x="562" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#134e4a">b₂=4</text>\n\n  <circle cx="614" cy="112" r="3.8" fill="#0d9488"/><circle cx="626" cy="112" r="3.8" fill="#0d9488"/><circle cx="638" cy="112" r="3.8" fill="#0d9488"/>\n  <circle cx="614" cy="124" r="3.8" fill="#0d9488"/><circle cx="626" cy="124" r="3.8" fill="#0d9488"/><circle cx="638" cy="124" r="3.8" fill="#0d9488"/>\n  <circle cx="614" cy="136" r="3.8" fill="#0d9488"/><circle cx="626" cy="136" r="3.8" fill="#0d9488"/><circle cx="638" cy="136" r="3.8" fill="#0d9488"/>\n  <text x="626" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#134e4a">b₃=9</text>\n\n  <text x="577" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#115e59">(1, 4, 9, 16, 25, 36, ...)</text>\n  <text x="577" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f766e">Bağıntı: aₙ₋₁ + aₙ = n² = bₙ</text>\n  <text x="577" y="222" text-anchor="middle" font-size="9.5" fill="#134e4a">(Ardışık 2 üçgensel toplamı = karesel)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
